async function sincronizarFGVSES2024Complementares(usuarioId: number) {
  const disciplinas = new Map<string, number>();
  const jaImportadas = await prisma.questao.findMany({
    where: { fonte: FONTE_PROVAS_REAIS }, select: { enunciado: true },
  });
  const normalizar = (v: string) => v.normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  const conhecidos = new Set(jaImportadas.map(x => normalizar(x.enunciado)));
  let inseridas = 0, existentes = 0, repetidas = 0;
  for (const lote of LOTES_SESMT_COMPLEMENTARES) {
    for (const q of lote.items) {
      if (!q.q.trim() || q.a.length !== 4 || !["A","B","C","D"].includes(q.k) ||
          q.a.some(a => !a.trim()) || new Set(q.a.map(a => a.normalize("NFD").toLowerCase().replace(/\s+/g, " ").trim())).size !== 4)
        throw new Error("[sesmt-complementares] Questão inválida: " + lote.key + ":" + q.n);
      const origemId = lote.prefix + String(q.n).padStart(2, "0");
      const existente = await prisma.questao.findFirst({
        where: { fonte: FONTE_PROVAS_REAIS, origemId }, select: { id: true },
      });
      if (existente) { existentes++; continue; }
      const hash = normalizar(q.q);
      if (conhecidos.has(hash)) { repetidas++; continue; }
      let disciplinaId = disciplinas.get(q.disciplina);
      if (!disciplinaId) {
        let disciplina = await prisma.disciplina.findFirst({
          where: { usuarioId, nome: { equals: q.disciplina, mode: "insensitive" } }, select: { id: true },
        });
        if (!disciplina) disciplina = await prisma.disciplina.create({
          data: { usuarioId, nome: q.disciplina }, select: { id: true },
        });
        disciplinaId = disciplina.id;
        disciplinas.set(q.disciplina, disciplinaId);
      }
      await prisma.questao.create({ data: {
        usuarioId, disciplinaId, fonte: FONTE_PROVAS_REAIS, origemId, tema: q.tema,
        dificuldade: "medio", banca: "FGV", ano: 2024,
        orgao: "Secretaria de Estado de Saúde de Mato Grosso", cargo: lote.cargo,
        fonteUrl: lote.url, enunciado: q.q,
        explicacao: "FGV/SES-MT 2024, " + lote.cargo + ", questão " + q.n +
          ". Gabarito definitivo: alternativa " + q.k +
          ". Prova: " + lote.url + " | Gabarito: " + GABARITO,
        alternativas: { create: q.a.map((texto, i) => ({
          texto: "ABCD"[i] + ") " + texto, correta: "ABCD"[i] === q.k,
        })) },
      }});
      conhecidos.add(hash);
      inseridas++;
    }
  }
  console.log("[sesmt-complementares] " + inseridas + " inseridas; " +
    existentes + " existentes; " + repetidas + " repetidas ignoradas.");
  return { inseridas, existentes, repetidas };
}

